import org.junit.Test;
import static org.junit.Assert.*;
import java.io.ByteArrayOutputStream;
import java.io.IOException;

public class CommentTest {

    @Test
    public void newCommentHasCorrectData() {
        Comment comment = new Comment("Some data");
        assertEquals("Some data", comment.getData());
    }

    @Test
    public void setDataReturnsCorrectValue() {
        Comment comment = new Comment("Old data");
        comment.setData("New data");
        assertEquals("New data", comment.getData());
    }

    @Test
    public void cloneCreatesDeepCopyOfComment() throws IOException {
        Comment comment = new Comment("Some data");
        Comment clonedComment = comment.clone();
        assertTrue(comment.getData().equals(clonedComment.getData()));
    }

    @Test
    public void outerHtmlHeadIncludesDataInOutput() throws IOException {
        ByteArrayOutputStream outContent = new ByteArrayOutputStream();
        Appendable accum = outContent;
        int depth = 0;
        Document.OutputSettings out = Document.OutputSettings.createEmptyDocument();
        Comment comment = new Comment("Some data");
        comment.outerHtmlHead(accum, depth, out);
        assertEquals("<!-- Some data -->", outContent.toString());
    }

    @Test
    public void outerHtmlTailIsEmpty() throws IOException {
        ByteArrayOutputStream outContent = new ByteArrayOutputStream();
        Appendable accum = outContent;
        int depth = 0;
        Document.OutputSettings out = Document.OutputSettings.createEmptyDocument();
        Comment comment = new Comment("");
        comment.outerHtmlTail(accum, depth, out);
        assertEquals("", outContent.toString());
    }

    @Test
    public void isXmlDeclarationReturnsFalse() {
        Comment comment = new Comment("Some data");
        assertFalse(comment.isXmlDeclaration());
    }

    @Test
    public void asXmlDeclarationReturnsNullForNonDeclaration() {
        Comment comment = new Comment("Some data");
        assertNull(comment.asXmlDeclaration());
    }
}
